/* cppi::704cee742fba274e7763c98649ee8ea23c06e50b3efcac23fd0238f0a125c319 */
Select run_id, business_date, extract_timestamp  from ci_capital_pipeline_sentry_holdings_staging 
where run_id = 'd9333504-6185-42df-8efc-72692c3ecd29'

/* cppi::9dcda2c15fd6729318256446a0615126ca1b9a11a3cc2dac458f2ab3daa73b32 */
select * from market.cppib_index_constituent 
where id_vendor_index = 'NIFTY' and id_cppib_security = 9047 and business_date = date'2025-06-13'

/* cppi::614bffb903862b4f7bf96c952d39132a90003480494b8fef91de03e01b9e2de5 */
select business_date as date_, security_id, 'SP500_45' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2023-11-30' and business_date <= date '2025-05-31' and weight_ndo>0 and id_cppib_index = 'SP500_45_GR_USD_0_0'

/* cppi::9334b633b01fea3944f04a73f709b583afb3b321df58ecc6af5432d05cc48762 */
